A bounded agent loop with budgets, tool validation and retries (the `llm` call is a generic placeholder):
```python
import time, json
from dataclasses import dataclass, field

class TransientToolError(Exception): ...
class ToolArgError(Exception): ...

@dataclass
class Budget:
    max_steps: int = 8
    max_cost_usd: float = 0.50
    max_seconds: float = 60
    steps: int = 0
    cost: float = 0.0
    started: float = field(default_factory=time.monotonic)

    def check(self):
        if self.steps >= self.max_steps: raise RuntimeError("step budget exhausted")
        if self.cost >= self.max_cost_usd: raise RuntimeError("cost budget exhausted")
        if time.monotonic() - self.started > self.max_seconds: raise RuntimeError("time budget exhausted")

def call_tool(tools, name, args, retries=3):
    if name not in tools:
        return {"error": f"unknown tool {name}; available: {sorted(tools)}"}
    fn, risk = tools[name]
    if risk == "irreversible" and not approved(name, args):    # human-in-the-loop gate
        return {"error": "approval denied or pending"}
    for attempt in range(retries):
        try:
            return {"ok": fn(**args)}
        except ToolArgError as e:
            return {"error": f"invalid arguments: {e}"}         # model may fix and retry
        except TransientToolError:
            time.sleep(min(2 ** attempt * 0.2, 2))              # backoff (add jitter in real code)
    return {"error": "tool unavailable after retries"}

def run_agent(goal, tools, llm, budget=None):
    budget = budget or Budget()
    messages, seen = [{"role": "user", "content": goal}], set()
    while True:
        budget.check()
        budget.steps += 1
        reply = llm(messages)                  # returns {"tool": name, "args": {...}} or {"final": text}
        budget.cost += reply.get("cost", 0.0)
        if "final" in reply:
            return reply["final"]
        sig = (reply["tool"], json.dumps(reply["args"], sort_keys=True))
        if sig in seen:                        # loop detection
            return "stopped: repeating the same action"
        seen.add(sig)
        result = call_tool(tools, reply["tool"], reply["args"])
        messages.append({"role": "tool", "content": json.dumps(result)[:2000]})   # truncate output
```
